   148  void Leader::HandleServerData(Coap::Message &aMessage, const Ip6::MessageInfo &aMessageInfo)
   149  {
   150      ThreadNetworkDataTlv networkData;
   151      ThreadRloc16Tlv      rloc16;
   152
   153      otLogInfoNetData("Received network data registration");
   154
   155      if (ThreadTlv::GetTlv(aMessage, ThreadTlv::kRloc16, sizeof(rloc16), rloc16) == OT_ERROR_NONE)
   156      {
   157          VerifyOrExit(rloc16.IsValid());
   158          RemoveBorderRouter(rloc16.GetRloc16(), kMatchModeRloc16);
   159      }
   160
   161      if (ThreadTlv::GetTlv(aMessage, ThreadTlv::kThreadNetworkData, sizeof(networkData), networkData) == OT_ERROR_NONE)
   162      {
   163          VerifyOrExit(networkData.IsValid());
   164          RegisterNetworkData(HostSwap16(aMessageInfo.mPeerAddr.mFields.m16[7]), networkData.GetTlvs(),
   165                              networkData.GetLength());
   166      }
   167
   168      SuccessOrExit(Get<Coap::Coap>().SendEmptyAck(aMessage, aMessageInfo));
   169
   170      otLogInfoNetData("Sent network data registration acknowledgment");
   171
   172  exit:
   173      return;
   174  }
