   740  otError Leader::RegisterNetworkData(uint16_t aRloc16, uint8_t *aTlvs, uint8_t aTlvsLength)
   741  {
   742      otError error         = OT_ERROR_NONE;
   743      bool    rlocIn        = false;
   744      bool    rlocStable    = false;
   745      bool    stableUpdated = false;
   746      bool    unused;
   747      uint8_t oldTlvs[NetworkData::kMaxSize];
   748      uint8_t oldTlvsLength = NetworkData::kMaxSize;
   749
   750      // Verify that `aTlvs` only contains entries matching `aRloc16`.
   751      SuccessOrExit(error = RlocLookup(aRloc16, rlocIn, rlocStable, aTlvs, aTlvsLength, kMatchModeRloc16,
   752                                       /* aAllowOtherEntries */ false));
   753
   754      RlocLookup(aRloc16, rlocIn, unused, mTlvs, mLength, kMatchModeRloc16);
   755
   756      if (rlocIn)
   757      {
   758          if (IsStableUpdated(aTlvs, aTlvsLength, mTlvs, mLength) || IsStableUpdated(mTlvs, mLength, aTlvs, aTlvsLength))
   759          {
   760              stableUpdated = true;
   761          }
   762
   763          // Store old Service IDs for given rloc16, so updates to server will reuse the same Service ID
   764          SuccessOrExit(error = GetNetworkData(false, oldTlvs, oldTlvsLength));
   765
   766          RemoveRloc(aRloc16, kMatchModeRloc16);
   767          SuccessOrExit(error = AddNetworkData(aTlvs, aTlvsLength, oldTlvs, oldTlvsLength));
   768
   769          mVersion++;
   770
   771          if (stableUpdated)
   772          {
   773              mStableVersion++;
   774          }
   775      }
   776      else
   777      {
   778          // No old data to be preserved, lets avoid memcpy() & FindService calls.
   779          SuccessOrExit(error = AddNetworkData(aTlvs, aTlvsLength, oldTlvs, 0));
   780
   781          mVersion++;
   782
   783          if (rlocStable)
   784          {
   785              mStableVersion++;
   786          }
   787      }
   788
   789      Get<Notifier>().Signal(OT_CHANGED_THREAD_NETDATA);
   790
   791  exit:
   792      return error;
   793  }
